const APPROVED_ANATOMICAL_MEDIA={...FILE_EXERCISE_MEDIA,...(window.GYM_EXERCISE_IMAGES||{})};
function exerciseMedia(id,e,extraClass=''){
  const src=APPROVED_ANATOMICAL_MEDIA[id];
  if(!src||!e)return '';
  const fallback=FILE_EXERCISE_MEDIA[id]||'';
  return `<div class="exercise-media anatomical-media ${extraClass}"><img src="${src}" data-fallback="${fallback}" alt="Ilustração anatômica de ${e.name}, com a musculatura trabalhada destacada" loading="lazy" decoding="async" onerror="if(this.dataset.fallback&&this.src!==new URL(this.dataset.fallback,document.baseURI).href){this.src=this.dataset.fallback;this.dataset.fallback=''}else{this.closest('.exercise-media').innerHTML='<span class='image-unavailable'>Imagem indisponível</span>'}"></div>`;
}
